function validate([low, high]) {
  const ok = (s) => typeof s === 'string' && /^[1-9][0-9]{0,99}$/.test(s);
  if (!ok(low) || !ok(high)) return 'low and high are 1 to 100 digits with no leading zero, and at least 1.';
  if (low.length > high.length || (low.length === high.length && low > high)) return 'low must not be larger than high.';
  return null;
}

