function countSteppingNumbers(low, high) {
  const MOD = 1e9 + 7;

  const countUpTo = (num) => {
    const n = num.length;
    const memo = Array.from({ length: n }, () => new Array(10).fill(-1));

    const dfs = (pos, prev, tight, started) => {
      if (pos === n) {
        return started ? 1 : 0;
      }
      if (started && !tight && memo[pos][prev] !== -1) {
        return memo[pos][prev];
      }
      const limit = tight ? Number(num[pos]) : 9;
      let ways = 0;
      for (let digit = 0; digit <= limit; digit++) {
        if (started && Math.abs(digit - prev) !== 1) {
          continue;
        }
        const nextTight = tight && digit === limit;
        const nextStarted = started || digit !== 0;
        ways = (ways + dfs(pos + 1, digit, nextTight, nextStarted)) % MOD;
      }
      if (started && !tight) {
        memo[pos][prev] = ways;
      }
      return ways;
    };

    return dfs(0, 0, true, false);
  };

  let lowIsStepping = true;
  for (let i = 1; i < low.length; i++) {
    if (Math.abs(low.charCodeAt(i) - low.charCodeAt(i - 1)) !== 1) {
      lowIsStepping = false;
    }
  }
  const answer = countUpTo(high) - countUpTo(low) + (lowIsStepping ? 1 : 0);
  return (answer % MOD + MOD) % MOD;
}

